-module(formata_yamerl_SUITE_construction_float).

-include_lib("eunit/include/eunit.hrl").

-define(FILENAME, "test/fixtures/yamerl/construction/float.yaml").

%% Formata fork: "-0" constructs -0.0. Since OTP 27 the pattern 0.0 no longer
%% matches -0.0, so the four upstream expectations of 0.0 for "-0" in the
%% failsafe+float and failsafe+float_ext tests are written as -0.0 here.

setup() ->
    ok.

schema_failsafe_simple_test_() ->
    {setup,
      fun setup/0,
      [
        ?_assertMatch(
          [
            [
              "0", "+0", "-0",
              "123", "+123", "-123",
              "12.34", "+12.34", "-12.34",
              "12e10", "+12e10", "-12e10",
              "1.2e11", "1.2e+11", "1.2e-11",
              "1.0e10", "1.0E10",
              ".", ".1", ".e+3", "1.", "1.e+3",
              "190:20:30.15", "+190:20:30.15", "-190:20:30.15",
              ".inf", "+.inf", "-.inf", ".nan",
              ".Inf", ".INF", ".iNF",
              ".NaN", ".NAN", ".Nan", ".nAN",
              "Not a float.0e+10", "+Not a float.0e+10", "-Not a float.0e+10"
            ]
          ],
          formata_yamerl_constr:file(?FILENAME,
            [{detailed_constr, false}, {schema, failsafe}]) %% No float parsing
        )
      ]
    }.

schema_failsafe_float_json_simple_test_() ->
    {setup,
      fun setup/0,
      [
        ?_assertMatch(
          [
            [
              0.0, "+0", 0.0,
              123.0, "+123", -123.0,
              12.34, "+12.34", -12.34,
              1.2e+11, "+12e10", -1.2e+11,
              1.2e+11, 1.2e+11, 1.2e-11,
              1.0e+10, 1.0e+10,
              ".", ".1", ".e+3", 1.0, 1000.0,
              "190:20:30.15", "+190:20:30.15", "-190:20:30.15",
              '+inf', "+.inf", '-inf', 'nan',
              ".Inf", ".INF", ".iNF",
              ".NaN", ".NAN", ".Nan", ".nAN",
              "Not a float.0e+10", "+Not a float.0e+10", "-Not a float.0e+10"
            ]
          ],
          formata_yamerl_constr:file(?FILENAME,
            [{detailed_constr, false}, {schema, failsafe},
              {node_mods, [formata_yamerl_node_float_json]}])
        )
      ]
    }.

schema_failsafe_float_simple_test_() ->
