              "1.0e10", "1.0E10",
              ".", 0.1, 0.0, 1.0, 1000.0,
              685230.15, 685230.15, -685230.15,
              '+inf', '+inf', '-inf', 'nan',
              '+inf', '+inf', ".iNF",
              'nan', 'nan', ".Nan", ".nAN",
              "Not a float.0e+10", "+Not a float.0e+10", "-Not a float.0e+10"
